#!/usr/bin/env node

'use strict';

var fs = require('fs');
var path = require('path');

var SKIP_DIRS = {
  '.git': true,
  '.locofy': true,
  node_modules: true,
  build: true,
  DerivedData: true,
};

function walkForFile(root, filename, maxDepth) {
  var matches = [];

  function walk(current, depth) {
    var entries;
    try {
      entries = fs.readdirSync(current);
    } catch (_error) {
      return;
    }

    for (var index = 0; index < entries.length; index += 1) {
      var name = entries[index];
      var entry = path.join(current, name);
      var stat;
      try {
        stat = fs.lstatSync(entry);
      } catch (_error) {
        continue;
      }

      if (stat.isFile() && name === filename) {
        matches.push(entry);
      } else if (stat.isDirectory() && !SKIP_DIRS[name] && depth < maxDepth) {
        walk(entry, depth + 1);
      }
    }
  }

  walk(root, 0);
  return matches;
}

function isFile(file) {
  try {
    return fs.statSync(file).isFile();
  } catch (_error) {
    return false;
  }
}

function isDirectory(directory) {
  try {
    return fs.statSync(directory).isDirectory();
  } catch (_error) {
    return false;
  }
}

function generatedComponentSources(generatedRoot, framework) {
  var extension = framework === 'swiftui' ? '.swift' : '.kt';
  var files = [];

  function walk(current, depth) {
    var entries;
    try {
      entries = fs.readdirSync(current);
    } catch (_error) {
      return;
    }

    for (var index = 0; index < entries.length; index += 1) {
      var name = entries[index];
      var entry = path.join(current, name);
      var stat;
      try {
        stat = fs.lstatSync(entry);
      } catch (_error) {
        continue;
      }

      if (stat.isDirectory() && !SKIP_DIRS[name] && depth < 14) {
        walk(entry, depth + 1);
        continue;
      }
      if (!stat.isFile() || path.extname(name) !== extension) {
        continue;
      }

      var relative = normalizePath(path.relative(generatedRoot, entry));
      var parts = relative.split('/');
      var parent = parts[parts.length - 2];
      if (
        framework === 'swiftui' &&
        (parent === 'Components' || parts.indexOf('UIComponents') !== -1)
      ) {
        files.push(entry);
      } else if (
        framework === 'jetpack-compose' &&
        (parent === 'components' || parts.indexOf('component') !== -1) &&
        ('/' + relative).indexOf('/src/main/java/') !== -1
      ) {
        files.push(entry);
      }
    }
  }

  walk(generatedRoot, 0);
  return files.sort();
}

function splitMarkdownRow(line) {
  return line
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map(function (cell) {
      return cell.trim().replace(/`/g, '');
    });
}

function parseGroups(file) {
  var rows = [];
  var headers = null;
  var lines = fs.readFileSync(file, 'utf8').split(/\r?\n/);

  for (var lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
    var line = lines[lineIndex];
    if (line.indexOf('|') !== 0) {
      if (headers && rows.length > 0) {
        break;
      }
      continue;
    }

    var cells = splitMarkdownRow(line);
    if (cells.indexOf('Raw generated names/files') !== -1) {
      headers = cells;
      continue;
    }
    if (
      !headers ||
      cells.every(function (cell) {
        return /^-+$/.test(cell);
      })
    ) {
      continue;
    }

    var row = {};
    for (var headerIndex = 0; headerIndex < headers.length; headerIndex += 1) {
      row[headers[headerIndex]] = cells[headerIndex] || '';
    }
    if (row['Raw generated names/files']) {
      rows.push(row);
    }
  }
  return rows;
}

function parseTypeAndFile(cell) {
  var clean = cell.trim().replace(/`/g, '');
  var separator = clean.indexOf(' / ');
  if (separator === -1) {
    return [clean, ''];
  }
  return [clean.slice(0, separator).trim(), clean.slice(separator + 3).trim()];
}

function rawNames(cell) {
  var names = [];
  var pattern = /(?:^|,\s*)([A-Za-z_][A-Za-z0-9_]*)\s*(?:\(|$)/g;
  var match;
  while ((match = pattern.exec(cell))) {
    names.push(match[1]);
  }
  return names;
}

function normalizeName(name, framework) {
  if (framework === 'jetpack-compose') {
    return name.replace(/[0-9]+$/, '');
  }
  return name
    .replace(/[0-9]+$/, '')
    .replace(/View$/, '')
    .replace(/[0-9]+$/, '')
    .replace(/View$/, '');
}

function canonicalType(key, framework) {
  return framework === 'swiftui' ? key + 'View' : key;
}

function isExcludedDeclaration(name) {
  return (
    /(?:Screen|Preview|App)$/.test(name) ||
    /(?:BottomNavigation|BottomNav|TopAppBar|AppTopBar|TabBar|TabItem|Navigation|NavHost|RootTab)/.test(
      name,
    )
  );
}

function declarationFromSource(file, framework) {
  var source = fs.readFileSync(file, 'utf8');
  var expectedName = path.basename(file, path.extname(file));
  var pattern =
    framework === 'swiftui'
      ? /\bstruct\s+([A-Za-z_][A-Za-z0-9_]*)\s*:[^{\n]*\bView\b/g
      : /@Composable[\s\S]{0,240}?\bfun\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(/g;
  var names = [];
  var match;
  while ((match = pattern.exec(source))) {
    names.push(match[1]);
  }
  return names.indexOf(expectedName) !== -1 ? expectedName : null;
}

function normalizePath(file) {
  var normalized = String(file).replace(/\\/g, '/');
  return normalized.indexOf('./') === 0 ? normalized.slice(2) : normalized;
}

function resolveProjectFile(projectRoot, expectedPath) {
  var directRoots = [
    projectRoot,
    path.dirname(projectRoot),
    path.dirname(path.dirname(projectRoot)),
  ];
  for (var index = 0; index < directRoots.length; index += 1) {
    var direct = path.resolve(directRoots[index], expectedPath);
    if (isFile(direct) && normalizePath(direct).indexOf('/.locofy/') === -1) {
      return direct;
    }
  }

  var wanted = normalizePath(expectedPath);
  var matches = walkForFile(projectRoot, path.basename(expectedPath), 10);
  for (var matchIndex = 0; matchIndex < matches.length; matchIndex += 1) {
    var relative = normalizePath(path.relative(projectRoot, matches[matchIndex]));
    var normalized = normalizePath(matches[matchIndex]);
    if (normalized.indexOf('/.locofy/') === -1 && relative.slice(-wanted.length) === wanted) {
      return matches[matchIndex];
    }
  }
  return null;
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function declarationExists(file, name, framework) {
  var source = fs.readFileSync(file, 'utf8');
  var escaped = escapeRegExp(name);
  var pattern =
    framework === 'swiftui'
      ? new RegExp('\\bstruct\\s+' + escaped + '\\s*:[^{\\n]*\\bView\\b')
      : new RegExp('@Composable[\\s\\S]{0,240}?\\bfun\\s+' + escaped + '\\s*\\(');
  return pattern.test(source);
}

function previewDeclarationExists(file, framework) {
  var source = fs.readFileSync(file, 'utf8');
  return framework === 'swiftui'
    ? /#Preview\b|\bPreviewProvider\b/.test(source)
    : /@Preview\b/.test(source);
}

function isNone(cell) {
  return ['', 'none', '-', '—'].indexOf(cell.trim().toLowerCase()) !== -1;
}

function lowerCamelCase(name) {
  return name.charAt(0).toLowerCase() + name.slice(1);
}

function isNestedComposeComponentLocation(file, name) {
  var parts = normalizePath(file).split('/');
  for (var index = 0; index < parts.length; index += 1) {
    if (parts[index] !== 'component') {
      continue;
    }
    if (
      parts[index - 1] !== 'ui' &&
      index + 2 === parts.length - 1 &&
      parts[index + 1] === lowerCamelCase(name) &&
      parts[parts.length - 1] === name + '.kt'
    ) {
      return true;
    }
  }
  return false;
}

function expectedCommonLocation(file, framework, name) {
  if (normalizePath(file).split('/').indexOf('.locofy') !== -1) {
    return false;
  }
  if (framework === 'swiftui') {
    var parts = normalizePath(file).split('/');
    var componentFolder = name.replace(/View$/, '');
    return (
      parts[parts.length - 3] === 'UIComponents' &&
      parts[parts.length - 2] === componentFolder &&
      /^[A-Z][A-Za-z0-9]*$/.test(parts[parts.length - 2]) &&
      parts[parts.length - 1] === name + '.swift'
    );
  }
  return isNestedComposeComponentLocation(file, name);
}

function verify(options) {
  var projectRoot = path.resolve(options.projectRoot);
  var groupsPath = path.resolve(options.groups);
  if (!isFile(groupsPath)) {
    return ['FAIL:EXPECTED_FIGMA_GROUPS_MISSING=' + groupsPath];
  }

  if (!process.env.LOCOFY_GENERATED_ROOT) {
    return ['FAIL:EXPECTED_FIGMA_GENERATED_ROOT_ENV_MISSING=LOCOFY_GENERATED_ROOT'];
  }
  var generatedRoot = path.resolve(process.env.LOCOFY_GENERATED_ROOT);
  if (!isDirectory(generatedRoot)) {
    return ['FAIL:EXPECTED_FIGMA_GENERATED_ROOT_MISSING=' + generatedRoot];
  }

  var groups = parseGroups(groupsPath);
  var groupsByRawName = Object.create(null);
  var failures = [];
  for (var groupIndex = 0; groupIndex < groups.length; groupIndex += 1) {
    var names = rawNames(groups[groupIndex]['Raw generated names/files']);
    if (names.length > 1) {
      var differences = groups[groupIndex]['Differences to merge'] || '';
      var callSites = groups[groupIndex]['Call sites'] || '';
      if (isNone(callSites)) {
        failures.push(
          'FAIL:EXPECTED_FIGMA_CALLER_MAPPING_MISSING=' +
            (groups[groupIndex]['Normalized key'] || names[0]),
        );
      }
      for (var mappedIndex = 0; mappedIndex < names.length; mappedIndex += 1) {
        if (
          differences.indexOf(names[mappedIndex]) === -1 ||
          !/\b(?:case|slot)\b/i.test(differences)
        ) {
          failures.push(
            'FAIL:EXPECTED_FIGMA_VARIANT_MAPPING_MISSING=' +
              names[mappedIndex] +
              ' key=' +
              (groups[groupIndex]['Normalized key'] || 'missing'),
          );
        }
      }
    }
    for (var nameIndex = 0; nameIndex < names.length; nameIndex += 1) {
      if (!groupsByRawName[names[nameIndex]]) {
        groupsByRawName[names[nameIndex]] = [];
      }
      groupsByRawName[names[nameIndex]].push(groups[groupIndex]);
    }
  }

  var expected = [];
  var sourcePaths = generatedComponentSources(generatedRoot, options.framework);
  if (sourcePaths.length === 0 && groups.length > 0) {
    var expectedFolder =
      options.framework === 'swiftui'
        ? 'Components/*.swift or UIComponents/<Base>/*.swift'
        : 'app/src/main/java/**/components/*.kt or app/src/main/java/**/component/<base>/*.kt';
    return ['FAIL:EXPECTED_FIGMA_GENERATED_COMPONENTS_MISSING=' + expectedFolder];
  }

  for (var sourceIndex = 0; sourceIndex < sourcePaths.length; sourceIndex += 1) {
    var sourcePath = sourcePaths[sourceIndex];
    var name = declarationFromSource(sourcePath, options.framework);
    if (!name) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_DECLARATION_MISSING=' +
          normalizePath(path.relative(generatedRoot, sourcePath)),
      );
      continue;
    }
    if (!isExcludedDeclaration(name)) {
      expected.push([name, sourcePath]);
    }
  }

  var rowsByKey = Object.create(null);
  var verifiedCompanionFiles = Object.create(null);
  for (var expectedIndex = 0; expectedIndex < expected.length; expectedIndex += 1) {
    var componentName = expected[expectedIndex][0];
    var matches = groupsByRawName[componentName] || [];
    if (matches.length === 0) {
      failures.push('FAIL:EXPECTED_FIGMA_COMPONENT_MISSING=' + componentName);
      continue;
    }
    if (matches.length > 1) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_COMPONENT_DUPLICATED=' + componentName + ' groups=' + matches.length,
      );
      continue;
    }

    var group = matches[0];
    var key = normalizeName(componentName, options.framework);
    var recordedKey = group['Normalized key'];
    if (recordedKey !== key) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_NORMALIZATION=' +
          componentName +
          ' expected_key=' +
          key +
          ' actual_key=' +
          recordedKey,
      );
    }

    var canonical = parseTypeAndFile(group['Canonical type/file']);
    var canonicalName = canonical[0];
    var canonicalFile = canonical[1];
    var existing = parseTypeAndFile(group['Existing target match']);
    var existingFile = existing[1];
    var expectedType = canonicalType(key, options.framework);
    if (isNone(group['Existing target match'])) {
      if (canonicalName !== expectedType) {
        failures.push(
          'FAIL:EXPECTED_FIGMA_CANONICAL=' +
            componentName +
            ' expected=' +
            expectedType +
            ' actual=' +
            canonicalName,
        );
      }
      if (!expectedCommonLocation(canonicalFile, options.framework, expectedType)) {
        var expectedLocation =
          options.framework === 'swiftui'
            ? 'UIComponents/<PascalCaseComponentName>/<File>.swift'
            : 'component/<camelCaseComponentName>/<File>.kt';
        failures.push(
          'FAIL:EXPECTED_FIGMA_LOCATION=' +
            componentName +
            ' canonical=' +
            canonicalFile +
            ' expected=' +
            expectedLocation,
        );
      }
    } else if (!existingFile || normalizePath(existingFile) !== normalizePath(canonicalFile)) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_EXISTING_LOCATION=' +
          componentName +
          ' existing=' +
          (existingFile || 'missing') +
          ' canonical=' +
          (canonicalFile || 'missing'),
      );
    }

    var finalFile = canonicalFile ? resolveProjectFile(projectRoot, canonicalFile) : null;
    var declaredType = isNone(group['Existing target match']) ? expectedType : canonicalName;
    if (!finalFile) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_FILE_MISSING=' +
          componentName +
          ' canonical=' +
          (canonicalFile || 'missing'),
      );
    } else if (!declarationExists(finalFile, declaredType, options.framework)) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_DEFINITION_MISSING=' +
          componentName +
          ' canonical=' +
          declaredType +
          ' file=' +
          canonicalFile,
      );
    }

    if (finalFile && !verifiedCompanionFiles[finalFile]) {
      verifiedCompanionFiles[finalFile] = true;
      if (options.framework === 'swiftui') {
        if (!previewDeclarationExists(finalFile, options.framework)) {
          failures.push(
            'FAIL:EXPECTED_FIGMA_PREVIEW_DECLARATION_MISSING=' +
              normalizePath(path.relative(projectRoot, finalFile)),
          );
        }
      } else {
        var colorsFile = path.join(path.dirname(finalFile), canonicalName + 'Colors.kt');
        var previewFile = path.join(path.dirname(finalFile), canonicalName + 'Preview.kt');
        if (!isFile(colorsFile)) {
          failures.push(
            'FAIL:EXPECTED_FIGMA_COLORS_FILE_MISSING=' +
              normalizePath(path.relative(projectRoot, colorsFile)),
          );
        }
        if (!isFile(previewFile)) {
          failures.push(
            'FAIL:EXPECTED_FIGMA_PREVIEW_FILE_MISSING=' +
              normalizePath(path.relative(projectRoot, previewFile)),
          );
        } else if (!previewDeclarationExists(previewFile, options.framework)) {
          failures.push(
            'FAIL:EXPECTED_FIGMA_PREVIEW_DECLARATION_MISSING=' +
              normalizePath(path.relative(projectRoot, previewFile)),
          );
        }
      }
    }

    if (!rowsByKey[key]) {
      rowsByKey[key] = [];
    }
    if (rowsByKey[key].indexOf(group) === -1) {
      rowsByKey[key].push(group);
    }
  }

  var keys = Object.keys(rowsByKey);
  for (var keyIndex = 0; keyIndex < keys.length; keyIndex += 1) {
    if (rowsByKey[keys[keyIndex]].length > 1) {
      failures.push(
        'FAIL:EXPECTED_FIGMA_GROUP_SPLIT=' +
          keys[keyIndex] +
          ' groups=' +
          rowsByKey[keys[keyIndex]].length,
      );
    }
  }

  if (failures.length === 0) {
    console.log(
      'OK:EXPECTED_FIGMA_COMPONENTS count=' +
        expected.length +
        ' groups=' +
        keys.length +
        ' generated=' +
        normalizePath(path.relative(projectRoot, generatedRoot)),
    );
  }
  return failures;
}

function parseArgs(argv) {
  var options = { projectRoot: '.' };
  for (var index = 0; index < argv.length; index += 1) {
    var arg = argv[index];
    if (arg === '--framework') {
      options.framework = argv[++index];
    } else if (arg === '--project-root') {
      options.projectRoot = argv[++index];
    } else if (arg === '--groups') {
      options.groups = argv[++index];
    } else {
      throw new Error('unknown argument: ' + arg);
    }
  }

  if (
    (options.framework !== 'swiftui' && options.framework !== 'jetpack-compose') ||
    !options.groups
  ) {
    throw new Error('--framework must be swiftui or jetpack-compose and --groups is required');
  }
  return options;
}

function main() {
  try {
    var failures = verify(parseArgs(process.argv.slice(2)));
    for (var index = 0; index < failures.length; index += 1) {
      console.log(failures[index]);
    }
    process.exitCode = failures.length > 0 ? 1 : 0;
  } catch (error) {
    console.log('FAIL:EXPECTED_FIGMA_PROBE_ERROR=' + error.message);
    process.exitCode = 1;
  }
}

if (require.main === module) {
  main();
}

module.exports = {
  verify: verify,
};
